// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;
    Log log_;

    function setUp() public { log_ = new Log(); c = new X_WALLET(address(log_)); }

    function testFuzz_property(uint256 amount, address actor, uint256 unlockTime, uint256 warpTime) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(this) && actor != address(c) && actor != address(log_));
        amount = bound(amount, 0, 100 ether);
        warpTime = bound(warpTime, 1, 2 seconds * 1000 * 365 days);
        vm.warp(warpTime);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        (address sender, , uint256 val, uint256 time) = log_.History(0);
        assertTrue(sender == actor && val == amount && time == warpTime);
    }
}
